body[data-atom-app=quick-notes] .note-entry>.actions button{padding:0;min-height:25px;flex:none;font-size:10px;background:transparent!important}
body[data-atom-app=quick-notes] .screen>.row>.actions button{background:transparent!important;font-size:12px;padding:4px 8px}
body[data-atom-app=quick-notes] .screen>.row>.actions button[data-action=new]{background:var(--atom-accent,#007aff)!important;color:white!important;border-radius:16px!important;padding:5px 13px}
body[data-atom-app=quick-notes] [data-action=save]{background:var(--atom-accent,#007aff)!important;color:#fff!important}
body[data-atom-app=today] header>button{background:var(--atom-accent,#007aff)!important;color:white!important;border-radius:18px!important}
body[data-atom-app=today] .check{background:transparent!important;border:1.5px solid var(--atom-line,#d3d8df)!important;border-radius:50%!important}
body[data-atom-app=today] .done .check{background:var(--atom-accent,#007aff)!important;color:white!important;border-color:transparent!important}
body[data-atom-app=today] .item>.small,body[data-atom-app=today] footer button{background:transparent!important}
body[data-atom-app=sound-lab] .play{background:var(--atom-accent,#007aff)!important;color:white!important;border-radius:22px!important}
body[data-atom-app=sound-lab] .step{background:#e1e5ed!important;border-radius:7px!important;border:2px solid transparent!important}
body[data-atom-app=sound-lab] .step.on{background:#377df6!important}body[data-atom-app=sound-lab] .step[data-track="1"].on{background:#9d7ed9!important}body[data-atom-app=sound-lab] .step[data-track="2"].on{background:#e6ac53!important}body[data-atom-app=sound-lab] .step[data-track="3"].on{background:#4faf9f!important}
body[data-atom-app=sound-lab] .step.playing{border-color:var(--atom-ink,#202124)!important}
body[data-atom-app=sound-lab] .pages button{background:transparent!important;border-radius:7px!important;color:var(--atom-secondary-text,#737985)!important}
body[data-atom-app=sound-lab] .pages .selected{background:var(--atom-card,#fff)!important;color:var(--atom-ink,#202124)!important}
body[data-atom-app=sound-lab] footer button{background:transparent!important}
body[data-atom-app=task-pal] .task{color:var(--atom-ink,#202124)!important;border:1px solid transparent!important;background:var(--atom-card,#fff)!important}
body[data-atom-app=task-pal] .task[aria-pressed=true]{border-color:var(--atom-accent,#007aff)!important;background:var(--atom-card,#fff)!important;color:var(--atom-ink,#202124)!important}
body[data-atom-app=pixel-lab] footer button{background:transparent!important;border-radius:10px!important}body[data-atom-app=pixel-lab] footer #pause{background:var(--atom-accent,#007aff)!important;color:#fff!important}
body[data-atom-app=official-companion] .top{background:transparent!important;padding:0!important;border-radius:0!important}
body[data-atom-app=official-companion] .controls button{background:transparent!important;border-radius:17px!important;color:var(--atom-ink,#202124)!important}
body[data-atom-app=official-companion] .controls button[aria-pressed=true]{background:var(--atom-accent,#007aff)!important;color:white!important}
body[data-atom-app=app-library] .open{background:transparent!important;color:var(--atom-ink,#202124)!important}
body[data-atom-app=app-library] .pin{background:var(--atom-paper,#f4f5f8)!important;border-radius:17px!important}
body[data-atom-app=my-computer] .workbench-tabs button{border-radius:0!important;background:transparent!important;color:var(--atom-secondary-text,#777b84)!important}
body[data-atom-app=my-computer] .workbench-tabs button[aria-pressed=true]{background:transparent!important;color:var(--atom-ink,#202124)!important;border-bottom:2px solid var(--atom-accent,#007aff)!important}
body[data-atom-app=my-computer] [data-action=submit]{background:var(--atom-accent,#007aff)!important;color:#fff!important;border-radius:18px!important}
